// templui component code — Xolo build.
//
// Diverges from the asset shipped by templui on two points:
//   - no light/dark theme swap: the product is light-only (cf. templui.css), and
//     only the light highlight.js stylesheet is vendored;
//   - the wait for window.hljs gives up instead of recursing on
//     requestAnimationFrame forever. Upstream assumes the CDN always answers, so
//     a blocked or missing highlight.js pinned a frame callback for the lifetime
//     of the page. highlight.js is now local and deferred, so a couple of frames
//     are enough — and an unhighlighted block is a perfectly good fallback.
(() => {
  "use strict";

  const MAX_FRAMES = 120; // ~2s at 60fps, then give up.

  function highlightAll() {
    if (!window.hljs) return;
    document
      .querySelectorAll("[data-tui-code-block]:not(.hljs)")
      .forEach((block) => window.hljs.highlightElement(block));
  }

  function whenReady(fn, frames) {
    if (window.hljs) {
      fn();
      return;
    }
    if (frames >= MAX_FRAMES) return;
    requestAnimationFrame(() => whenReady(fn, frames + 1));
  }

  whenReady(highlightAll, 0);

  // Re-run on DOM changes so blocks swapped in by hx-boost get highlighted too.
  new MutationObserver(highlightAll).observe(document.documentElement, {
    childList: true,
    subtree: true,
  });
})();
